def is_prime(n):
    if n <= 1:
        return False
    if n == 2:
        return True
    if n % 2 == 0:
        return False
    for i in range(3, int(n**0.5) + 1, 2):
        if n % i == 0:
            return False
    return True

def check_a(a, limit=10):
    for x in range(-limit, limit + 1):
        if is_prime(x**4 + a**2):
